103:  *   3. `something.member` — fall back to recursive parse of `something`.
104:  */
105: function parseReceiver(
106:   receiver: string
107: ): { targetSymbol: string | null; interfaceName: string | null } {
108:   const trimmed = receiver.trim();
109: 
110:   // Shape 1: `IFoo(EXPR)` — only if the whole receiver is that form.
111:   const interfaceMatch = /^([A-Z][A-Za-z0-9_]*)\s*\(([\s\S]*)\)$/.exec(trimmed);
112:   if (interfaceMatch && balanced(interfaceMatch[2]!)) {
113:     const interfaceName = interfaceMatch[1]!;
114:     const inner = interfaceMatch[2]!.trim();
115:     return {
116:       interfaceName,
117:       targetSymbol: extractInnermostIdentifier(inner),
118:     };
119:   }
